#define PI 3.14159265359
// 2D Random
float random(in vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float random2(in vec2 st) {
    return fract(sin(dot(st.xy, vec2(15.9898, 98.233))) * 43758.5453123);
}

// 2D Noise based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise(in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    // Smooth Interpolation

    // Cubic Hermine Curve.  Same as SmoothStep()
    vec2 u = f * f * (3.0 - 2.0 * f);
    // u = smoothstep(0.,1.,f);

    // Mix 4 coorners percentages
    return mix(a, b, u.x) +
        (c - a) * u.y * (1.0 - u.x) +
        (d - b) * u.x * u.y;
}

vec2 rotate2d(vec2 _st, float _angle) {
    _st -= vec2(0.5);
    mat2 rotate = mat2(cos(_angle), -sin(_angle), sin(_angle), cos(_angle));
    _st = rotate * _st;
  //_st += vec2(0.5);
    return _st;
}

float field(in vec2 _st, in float _field, in float _width) {
    return 1. - smoothstep(_width, _width + 0.01, _field) * smoothstep(_field, _field + 0.01, _width + 0.1);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     const float N = 4.;
    vec2 st = gl_FragCoord.xy / iResolution.xy;
    vec2 st2 = st;
    st *= 2.;
    st.x += iTime * 0.5;
    vec3 color = vec3(1.0);
    for(float i = 0.; i < N; i++) {
        st = rotate2d(st, PI * random(vec2(N)));
        vec2 pos = vec2(st.x * 5., st.y * random(vec2(N)) * 15.0);
        float n = noise(pos);
        color *= vec3(field(st, n, 0.5));
    }
    color += smoothstep(0.8, 1., st2.x) * 1.;

  /* vec2 pos = vec2(st.x * 5., st.y * 10.0);
  float n = noise(pos);
  color = vec3(field(st, n, 0.5)); */

    fragColor = vec4(vec3(color), 1.0);
}
